modSuffix =[]
modRemaining = "--:--"
}
function modParseTime(value){
var parts = String(value).split(":")
if(parts.length < 2 || parts.length > 3)return -1
var seconds = 0
for(var i = 0;i < parts.length;i++){
if(!parts[i].length)return -1
var number = Number(parts[i])
if(!isFinite(number)|| number < 0 || Math.floor(number)!== number)return -1
if(i > 0 && number >= 60)return -1
seconds = seconds * 60 + number
}
return seconds
}
function modFormatTime(seconds){
function pad(number){return number < 10 ? "0" + number:String(number)}
if(seconds >= 3600)
return Math.floor(seconds / 3600)+ ":" + pad(Math.floor(seconds / 60)% 60)+ ":" + pad(seconds % 60)
return Math.floor(seconds / 60)+ ":" + pad(seconds % 60)
}
function modStep(){QueueCache.step(screen,modRows)}
function modUpdateRemaining(){
modRemaining = "--:--"
if(!modReady || view_index < 0 || view_index >= modDurations.length)return
try{
var names =["MusicPlayer","MusicPlayerSpectrum","MusicPlayerLevelMeter",
"MusicPlayerDigitalLevelMeter"]
var neighbors =[screenController.leftController,screenController.rightController,
screenController.upperController,screenController.lowerController]
for(var n = 0;n < neighbors.length;n++)
if(neighbors[n]&& names.indexOf(neighbors[n].screenID)>= 0)
names.unshift(neighbors[n].screenID)
for(var j = 0;j < names.length;j++){
var clock = screenController.properties[names[j]]
if(!clock || Number(clock.total_playtrack_num)!== modDurations.length
|| Number(clock.currentry_playtrack_num)!== view_index + 1)continue
if(typeof clock.is_shuffle === "boolean"){if(modShuffle!==null && modShuffle!==clock.is_shuffle){modReset();return}modShuffle=clock.is_shuffle}
var elapsed = Number(clock.currently_playing_time)
if(!isFinite(elapsed)|| elapsed < 0
|| elapsed >(modDurations[view_index]+ 2)* 1000)continue
var played = Math.min(modDurations[view_index],Math.floor(elapsed / 1000))
modRemaining = modFormatTime(Math.max(0,modSuffix[view_index]- played))
return
}
}catch(error){
console.log("QR clock",error)
}
}
