function setInitialPosition(selected_index,cell_height,content_height,height)
{
var contentY = 0
var initialPosition = 2
if(content_height < height || selected_index < 0)
{
contentY = 0
}else{
if(selected_index >= initialPosition)
{
contentY =((selected_index - initialPosition)* cell_height)+ parseInt(cell_height / 2)
}
if(contentY > content_height - height)
{
contentY = content_height - height
}
}
return contentY
}
